begin; create extension if not exists pgtap with schema extensions; select extensions.no_plan();
update public.profiles set account_status='active' where id::text like 'f9100000-%'; update public.profiles set app_role='super_admin' where id='f9100000-0000-4000-8000-000000000001'; update public.profiles set app_role='admin' where id in ('f9100000-0000-4000-8000-000000000002','f9100000-0000-4000-8000-000000000003'); update public.profiles set app_role='staff' where id in ('f9100000-0000-4000-8000-000000000004','f9100000-0000-4000-8000-000000000005','f9100000-0000-4000-8000-000000000006','f9100000-0000-4000-8000-000000000015'); update public.profiles set account_status='pending' where id='f9100000-0000-4000-8000-000000000010'; update public.profiles set account_status='rejected' where id='f9100000-0000-4000-8000-000000000011'; update auth.users set email_confirmed_at=null where id='f9100000-0000-4000-8000-000000000012'; update auth.users set banned_until=now()+interval '1 hour' where id='f9100000-0000-4000-8000-000000000013'; update auth.users set is_anonymous=true where id='f9100000-0000-4000-8000-000000000014';
select extensions.ok(not has_function_privilege('anon','securedesk_private.auto_close_resolved_tickets(integer)','EXECUTE'),'anon cannot run auto-close');
select extensions.ok(not has_schema_privilege('anon','cron','USAGE'),'anon cannot schedule jobs');
select extensions.ok(not has_function_privilege('authenticated','securedesk_private.auto_close_resolved_tickets(integer)','EXECUTE'),'authenticated cannot run auto-close');
select extensions.ok(not has_schema_privilege('authenticated','cron','USAGE'),'authenticated cannot schedule jobs');
select extensions.ok(not has_function_privilege('service_role','securedesk_private.auto_close_resolved_tickets(integer)','EXECUTE'),'service_role cannot run auto-close');
select extensions.ok(not has_schema_privilege('service_role','cron','USAGE'),'service_role cannot schedule jobs');
select extensions.ok(not (select prosecdef from pg_proc where oid='securedesk_private.auto_close_resolved_tickets(integer)'::regprocedure),'Worker does not elevate caller');
select extensions.is((select count(*)::integer from cron.job where jobname='securedesk-ticket-auto-close' and username='postgres' and active and schedule='* * * * *'),1,'One active owner cron job');
select extensions.ok(securedesk_private.ticket_auto_close_due('2026-03-22 03:00+02','2026-03-29 01:00Z'),'168h across DST');
select extensions.is(securedesk_private.ticket_auto_close_due('2026-10-01 00:00Z'::timestamptz,'2026-10-08 00:00Z'::timestamptz-interval '1 microsecond'),false,'Before boundary');
select extensions.is(securedesk_private.ticket_auto_close_due('2026-10-01 00:00Z'::timestamptz,'2026-10-08 00:00Z'::timestamptz),true,'At boundary');
select extensions.is(securedesk_private.ticket_auto_close_due('2026-10-01 00:00Z'::timestamptz,'2026-10-08 00:00Z'::timestamptz+interval '1 microsecond'),true,'After boundary');
select extensions.is(securedesk_private.ticket_auto_close_due(null,clock_timestamp()),false,'Null resolution cannot close');
select extensions.is(securedesk_private.ticket_auto_close_due(clock_timestamp(),null),false,'Caller cannot omit time');
select set_config('request.jwt.claims','',true);select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets(null)$t$,'22023',null,'Invalid batch null');
select set_config('request.jwt.claims','',true);select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets(0)$t$,'22023',null,'Invalid batch 0');
select set_config('request.jwt.claims','',true);select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets(1001)$t$,'22023',null,'Invalid batch 1001');
select set_config('request.jwt.claims','',true);select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets(-1)$t$,'22023',null,'Invalid batch -1');
select set_config('request.jwt.claims','{"sub":"f9100000-0000-4000-8000-000000000001","role":"authenticated"}',true);select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets()$t$,'42501',null,'Even owner session with business JWT is not scheduler');
select set_config('request.jwt.claims','',true);update public.tickets set resolved_at=clock_timestamp()-interval '8 days' where id='f9400000-0000-4000-8000-000000000008';
select extensions.is(securedesk_private.auto_close_resolved_tickets(),1,'Only expired no-Pending active ticket closes');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000004'),'Closed','Eligible fixture closed');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000002'),'Resolved','Recent resolution preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000008'),'Resolved','Inactive company preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000001'),'In Progress','Noneligible fixture 1 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000005'),'Open','Noneligible fixture 5 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000006'),'Closed','Noneligible fixture 6 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000010'),'Resolved','Noneligible fixture 10 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000012'),'Resolved','Noneligible fixture 12 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000015'),'Resolved','Noneligible fixture 15 preserved');
select extensions.is((select status from public.tickets where id='f9400000-0000-4000-8000-000000000020'),'Resolved','Noneligible fixture 20 preserved');
select extensions.is((select count(*)::integer from public.audit_logs where event_type='ticket.auto_closed' and target_id='f9400000-0000-4000-8000-000000000004'),1,'One close audit');
select extensions.ok((select actor_user_id is null and metadata_redacted->>'actor_kind'='system' and outcome='success' from public.audit_logs where event_type='ticket.auto_closed' and target_id='f9400000-0000-4000-8000-000000000004'),'System actor and success, no fake user');
select extensions.ok((select close_reason like 'Automatically closed%' and closed_at>=resolved_at+interval '168 hours' from public.tickets where id='f9400000-0000-4000-8000-000000000004'),'Server timestamp and recorded reason');
select extensions.is(securedesk_private.auto_close_resolved_tickets(),0,'Repeated job changes nothing');
select extensions.is((select count(*)::integer from public.audit_logs where event_type='ticket.auto_closed' and target_id='f9400000-0000-4000-8000-000000000004'),1,'Repeated job creates no second audit');
create function securedesk_private.auto_close_test_fault() returns trigger language plpgsql as $$ begin if new.event_type='ticket.auto_closed' and new.target_id='f9400000-0000-4000-8000-000000000102' then raise exception 'Fictional audit fault';end if;return new;end;$$;create trigger auto_close_test_fault before insert on public.audit_logs for each row execute function securedesk_private.auto_close_test_fault();
select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets(3)$t$,'P0001','Fictional audit fault','Late audit failure rolls back the batch');
select extensions.is((select count(*)::integer from public.tickets where id between 'f9400000-0000-4000-8000-000000000101' and 'f9400000-0000-4000-8000-000000000103' and status='Resolved'),3,'Entire failed batch remains Resolved');
select extensions.is((select count(*)::integer from public.audit_logs where event_type='ticket.auto_closed' and target_id between 'f9400000-0000-4000-8000-000000000101' and 'f9400000-0000-4000-8000-000000000103'),0,'Entire failed batch has no audit');
drop trigger auto_close_test_fault on public.audit_logs;drop function securedesk_private.auto_close_test_fault();
select extensions.is(securedesk_private.auto_close_resolved_tickets(2),2,'Successful batch limit two');
select extensions.is(securedesk_private.auto_close_resolved_tickets(2),1,'Next batch closes remaining one');
select extensions.is(securedesk_private.auto_close_resolved_tickets(2),0,'Drained work remains idempotent');
select set_config('request.jwt.claims','{"sub":"f9100000-0000-4000-8000-000000000001","role":"authenticated"}',true);set local role authenticated;select extensions.throws_ok($t$select securedesk_private.auto_close_resolved_tickets()$t$,'42501',null,'Business Super Admin SQL role cannot execute scheduler');reset role;select set_config('request.jwt.claims','',true);
select * from extensions.finish();rollback;
